{
  "items": [
    {
      "name": "MvPolynomial.aeval_natDegree_le",
      "type": " {σ : Type v} {R : Type u_2} [CommSemiring R] {m n : ℕ} (F : MvPolynomial σ R) (hF : F.totalDegree ≤ m) (f : σ → Polynomial R) (hf : ∀ (i : σ), (f i).natDegree ≤ n) : ((MvPolynomial.aeval f) F).natDegree ≤ m * n",
      "module": "Mathlib.RingTheory.Polynomial.Basic"
    },
    {
      "name": "Polynomial.aeval_homogenize_X_one",
      "type": " {R : Type u_1} [CommSemiring R] (p : Polynomial R) {n : ℕ} (hn : p.natDegree ≤ n) : (MvPolynomial.aeval ![Polynomial.X, 1]) (p.homogenize n) = p",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    },
    {
      "name": "Polynomial.aeval_homogenize_of_eq_one",
      "type": " {R : Type u_1} [CommSemiring R] {A : Type u_2} [CommSemiring A] [Algebra R A] {p : Polynomial R} {n : ℕ} (hn : p.natDegree ≤ n) (g : Fin 2 → A) (hg : g 1 = 1) : (MvPolynomial.aeval g) (p.homogenize n) = (Polynomial.aeval (g 0)) p",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    }
  ]
}
